// Development-only shape checking. Add Webhook Header Auth before external exposure.
const incoming = $input.first().json;
const ev = incoming && incoming.body ? incoming.body : incoming;
const errors = [];
const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const finite = x => typeof x === 'number' && Number.isFinite(x);
if (!object(ev)) {
  errors.push('Event must be a JSON object.');
} else {
  if (ev.contract_version !== '1.0') errors.push('contract_version must be 1.0.');
  if (ev.event !== 'session.completed') errors.push('event must be session.completed.');
  if (typeof ev.request_id !== 'string' || !ev.request_id.trim()) errors.push('request_id is required.');
  if (!object(ev.session)) {
    errors.push('session object is required.');
  } else {
    if (!Number.isInteger(ev.session.session_id) || ev.session.session_id < 1) errors.push('session.session_id must be a positive integer.');
    if (typeof ev.session.exercise !== 'string' || !ev.session.exercise) errors.push('session.exercise is required.');
    if (!Number.isInteger(ev.session.total_reps) || ev.session.total_reps < 0) errors.push('session.total_reps must be a nonnegative integer.');
    if (!finite(ev.session.mean_rom) || ev.session.mean_rom < 0) errors.push('session.mean_rom must be a nonnegative number.');
    if (!Array.isArray(ev.session.reps)) errors.push('session.reps must be an array.');
    if (ev.session.mean_quality != null && (!finite(ev.session.mean_quality) || ev.session.mean_quality < 0 || ev.session.mean_quality > 1)) errors.push('session.mean_quality must be between 0 and 1 or null.');
  }
  if (!object(ev.prescription)) {
    errors.push('prescription object is required.');
  } else {
    if (!finite(ev.prescription.target_reps) || ev.prescription.target_reps <= 0) errors.push('prescription.target_reps must be positive.');
    if (!finite(ev.prescription.target_rom) || ev.prescription.target_rom <= 0) errors.push('prescription.target_rom must be positive.');
  }
  if (!Array.isArray(ev.history)) {
    errors.push('history must be an array (empty for first session).');
  } else if (ev.history.some(h => !object(h) || !finite(h.mean_rom))) {
    errors.push('Every history item must have a numeric mean_rom.');
  }
}
// Preserve body wrapper so A1 code works unchanged behind Webhook.
return [{ json: {ok: errors.length === 0, errors, body: ev} }];

/**
 * PhysioTrack A1 Metrics Engine
 * n8n Code node; Run Once for All Items.
 * Input: {body: session.completed event} from Webhook, or bare event.
 * Output: {ev, metrics}. No LLM calls.
 */

// Preliminary thresholds — agree final values with a physiotherapist.
const CONFIG = {
  fastRepMaxSeconds: 1.0,
  baselineSessions: 3,
  slopeMinSessions: 3,
  quality: { good: 0.75, fair: 0.50 },
};

// Accept the Webhook's {body:...} wrapper or a bare fixture.
const input = $input.first().json;
const ev = input && input.body ? input.body : input;
const s = ev.session || {};
const rx = ev.prescription || {};
const reps = Array.isArray(s.reps) ? s.reps : [];
const hist = Array.isArray(ev.history) ? ev.history : []; // newest first

const round0 = (x) => x === null ? null : Math.round(x);
const round1 = (x) => x === null ? null : +x.toFixed(1);
const round2 = (x) => x === null ? null : +x.toFixed(2);
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const pct = (num, den) => isNum(num) && isNum(den) && den > 0 ? 100 * num / den : null;

const faultCounts = {};
for (const r of reps) {
  for (const f of (Array.isArray(r.faults) ? r.faults : [])) {
    if (f && typeof f.code === 'string' && f.code) {
      faultCounts[f.code] = (faultCounts[f.code] || 0) + 1;
    }
  }
}

const fastReps = reps.filter(r => isNum(r.duration_s) && r.duration_s < CONFIG.fastRepMaxSeconds).length;
const fastRepShare = reps.length ? round2(fastReps / reps.length) : null;

// History newest first -> reverse to oldest first, then current session.
const series = [...hist].reverse().map(h => h.mean_rom).concat([s.mean_rom]).filter(isNum);
let slope = null;
const n = series.length;
if (n >= CONFIG.slopeMinSessions) {
  const xMean = (n - 1) / 2;
  const yMean = series.reduce((a, b) => a + b, 0) / n;
  let num = 0;
  let den = 0;
  series.forEach((y, x) => {
    num += (x - xMean) * (y - yMean);
    den += (x - xMean) ** 2;
  });
  slope = den ? round2(num / den) : null;
}

// Mean of up to three latest past sessions. Null if history is empty.
const baseWin = hist.slice(0, CONFIG.baselineSessions).map(h => h.mean_rom).filter(isNum);
const baselineRom = baseWin.length ? round1(baseWin.reduce((a, b) => a + b, 0) / baseWin.length) : null;

let qualityBand = null;
if (isNum(s.mean_quality)) {
  qualityBand = s.mean_quality >= CONFIG.quality.good ? 'good'
              : s.mean_quality >= CONFIG.quality.fair ? 'fair'
              : 'poor';
}

const metrics = {
  reps_vs_target_pct: round0(pct(s.total_reps, rx.target_reps)),
  rom_vs_target_pct: round0(pct(s.mean_rom, rx.target_rom)),
  fault_counts: faultCounts,
  fast_rep_share: fastRepShare,
  rom_slope_deg_per_session: slope,
  baseline_rom: baselineRom,
  quality_band: qualityBand,
  incomplete_attempts: isNum(s.incomplete_attempts) ? s.incomplete_attempts : 0,
  sessions_in_history: hist.length,
};

return [{json: {ev, metrics}}];

// Return validation failures without echoing patient session data.
const {errors} = $input.first().json;
return [{json: {ok:false, errors}}];
